// The API this skill covers, read from kit/operations.json, and the argument check every call
// goes through. Part of a skill generated by spec2skill; plain ESM for Node.js 20+, no dependencies.
import { readFileSync } from 'node:fs';

/** `{ skill, kind, servers, envPrefix, auth, operations, chains }`, see kit/operations.json. */
export const api = JSON.parse(readFileSync(new URL('./operations.json', import.meta.url), 'utf8'));
const byId = new Map(api.operations.map((op) => [op.id, op]));

export class ArgsError extends Error {
  name = 'ArgsError';
}

/** The operation (or tool) with this id; throws for an id the API does not have. */
export function operation(id) {
  const op = byId.get(id);
  if (!op) throw new ArgsError(`unknown operation "${id}": use an id from kit/operations.json`);
  return op;
}

const typeOf = (v) => (v === null ? 'null' : Array.isArray(v) ? 'array' : Number.isInteger(v) ? 'integer' : typeof v);
const fits = (type, v) =>
  !type || type.split('|').some((t) => t === 'file' || t === typeOf(v) || (t === 'number' && typeof v === 'number'));

/**
 * Checks `args` against the operation's declared inputs: no unknown names, every required one
 * present, JSON types and enums respected. Throws an ArgsError naming the argument; returns the operation.
 */
export function validateArgs(id, args = {}) {
  const op = operation(id);
  const names = op.inputs.map((p) => p.name);
  for (const name of Object.keys(args)) {
    if (!names.includes(name)) throw new ArgsError(`${id}: unknown argument "${name}" (takes ${names.join(', ') || 'none'})`);
  }
  for (const p of op.inputs) {
    const v = args[p.name];
    if (v === undefined && p.required) throw new ArgsError(`${id}: missing required argument "${p.name}"`);
    if (v === undefined || (v === null && p.nullable)) continue;
    if (!fits(p.type, v)) throw new ArgsError(`${id}: argument "${p.name}" must be ${p.type}, got ${typeOf(v)}`);
    if (p.enum && !p.enum.includes(v)) throw new ArgsError(`${id}: argument "${p.name}" must be one of ${p.enum.join(', ')}`);
  }
  return op;
}
